// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address payable receiver = payable(address(0x123));
        uint amount = 1 ether;
        // Prank as a non-owner address
        vm.prank(address(0x456));
        // The reference version has owner = msg.sender (our test deployer), so this call will succeed (transfer to receiver)
        // The buggy version has owner = address(0), so the require will fail (msg.sender != owner) and the call will revert
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: owner is deployer (non-zero), require passes -> ok true
        // Buggy: owner is address(0), require fails -> ok false
        assertTrue(ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Actor is any address other than the deployer (msg.sender in constructor)
        address attacker = address(0x1234);
        // Fund the actor with 1 ether to be able to send
        vm.deal(attacker, 1 ether);
        // Try to send 0.5 ether to another address via the contract
        address receiver = address(0x5678);
        vm.prank(attacker);
        // We need to catch the revert because the buggy version might not revert
        bool ok;
        try c.sendTo(receiver, 0.5 ether) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the REFERENCE version, attacker != owner => require fails => ok = false
        // In the BUGGY version, owner = address(0), attacker != address(0) => require passes => ok = true
        assertTrue(!ok);
    }
}

